// ============================================================
//  Accept a scan from EITHER the MQTT input OR the HTTP input,
//  clean it up, and drop repeat taps of the same card.
// ============================================================

// --- 1. Normalise the payload shape -------------------------
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = { uid: p }; }
}

// --- 2. Clean the UID: uppercase hex characters only ---------
const uid = String(p.uid || '').toUpperCase().replace(/[^0-9A-F]/g, '');
if (!uid) {
    node.warn('Scan received with no usable UID: ' + JSON.stringify(p));
    return null;
}

// --- 3. Trust the ESP32 clock only if NTP actually synced ----
let when = new Date();
if (p.timestamp) {
    const t = new Date(p.timestamp);
    if (!isNaN(t.getTime())) { when = t; }
}

// --- 4. Duplicate guard -------------------------------------
// Same card at the same door inside the cooldown = a repeat tap,
// not a second arrival. Change COOLDOWN_MS to suit your school.
const COOLDOWN_MS = 5 * 60 * 1000;          // 5 minutes
const seen = flow.get('lastSeen') || {};
const key  = uid + '@' + (p.device || 'unknown');
const dup  = seen[key] && (Date.now() - seen[key] < COOLDOWN_MS);
seen[key]  = Date.now();
flow.set('lastSeen', seen);

msg.scan = {
    uid:       uid,
    device:    p.device || 'unknown',
    when:      when,
    duplicate: !!dup
};
return msg;

// ============================================================
//  Match the UID against the student registry held in
//  flow context (loaded from students.json at start-up).
// ============================================================
const db  = flow.get('students') || {};
const rec = db[msg.scan.uid] || null;

msg.student = rec;
msg.result  = !rec ? 'unknown'
                   : (msg.scan.duplicate ? 'duplicate' : 'ok');

// Pre-format date and time once so every downstream node agrees.
const d   = msg.scan.when;
const pad = function (n) { return String(n).padStart(2, '0'); };
msg.fmt = {
    date: d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()),
    time: pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds())
};

node.status({
    fill:  msg.result === 'ok' ? 'green' : 'yellow',
    shape: 'dot',
    text:  msg.scan.uid + ' -> ' + msg.result
});
return msg;

// ============================================================
//  One CSV line per attendance record.
//  Quotes are doubled so names containing commas survive.
//  Column order must match the header you create once by hand:
//  Date,Time,StudentID,Name,Class,UID,Device
// ============================================================
const s = msg.student;
const f = msg.fmt;
const q = function (v) {
    return '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
};

msg.payload = [
    q(f.date),
    q(f.time),
    q(s.studentId),
    q(s.name),
    q(s.className),
    q(msg.scan.uid),
    q(msg.scan.device)
].join(',');
return msg;

// ============================================================
//  Parent notification via the Telegram Bot API.
//  No contrib node needed - a plain http request node does it.
//
//  SECURITY: keep the bot token OUT of this flow. Set an
//  environment variable TELEGRAM_BOT_TOKEN before starting
//  Node-RED, or add it under the flow's "Environment" tab.
// ============================================================
const TOKEN = env.get('TELEGRAM_BOT_TOKEN') || 'YOUR_TELEGRAM_BOT_TOKEN';
if (TOKEN === 'YOUR_TELEGRAM_BOT_TOKEN') {
    node.warn('TELEGRAM_BOT_TOKEN is not set - notification skipped');
    return null;
}

const s = msg.student;
if (!s.parentChatId) {
    node.warn('No parentChatId for ' + s.name + ' - notification skipped');
    return null;
}

const text =
    'Attendance Alert\n\n' +
    s.name + ' (' + s.studentId + ') has arrived at school at ' +
    msg.fmt.time + ' on ' + msg.fmt.date + '.\n' +
    'Entry point: ' + msg.scan.device;

msg.method  = 'POST';
msg.url     = 'https://api.telegram.org/bot' + TOKEN + '/sendMessage';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { chat_id: s.parentChatId, text: text };
return msg;

// ============================================================
//  OPTIONAL: mirror the same row into a Google Sheet.
//
//  Deploy google-apps-script.gs as a Web App, then set an
//  environment variable SHEETS_WEBAPP_URL to the /exec URL.
//  If the variable is missing this branch quietly does nothing.
// ============================================================
const url = env.get('SHEETS_WEBAPP_URL');
if (!url) { return null; }

const s = msg.student;
msg.method  = 'POST';
msg.url     = url;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    date:      msg.fmt.date,
    time:      msg.fmt.time,
    studentId: s.studentId,
    name:      s.name,
    className: s.className,
    uid:       msg.scan.uid,
    device:    msg.scan.device
};
return msg;

// ============================================================
//  Build the two 16-character lines the ESP32 prints on the LCD.
//  Fed by all three switch outputs, so every tap gets an answer.
// ============================================================
const s = msg.student;
let line1, line2;

if (msg.result === 'ok') {
    line1 = 'Welcome!';
    line2 = s.name;
} else if (msg.result === 'duplicate') {
    line1 = 'Already Tapped';
    line2 = s ? s.name : msg.scan.uid;
} else {
    line1 = 'Unknown Card';
    line2 = msg.scan.uid;
}

msg.topic   = 'school/attendance/ack';
msg.payload = {
    status: msg.result,
    uid:    msg.scan.uid,
    name:   s ? s.name : '',
    line1:  String(line1).substring(0, 16),
    line2:  String(line2).substring(0, 16)
};
return msg;

// ============================================================
//  Unregistered card. Log the UID so you can copy it straight
//  into students.json and enrol the student.
//  Header: Date,Time,UID,Device
// ============================================================
const q = function (v) {
    return '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
};
msg.payload = [
    q(msg.fmt.date),
    q(msg.fmt.time),
    q(msg.scan.uid),
    q(msg.scan.device)
].join(',');
return msg;
